    34→import javax.script.ScriptException;
    35→
    36→public class JavaScriptTieredBrokerSelectorStrategy implements TieredBrokerSelectorStrategy
    37→{
    38→  public interface SelectorFunction
    39→  {
    40→    String apply(TieredBrokerConfig config, Query query);
    41→  }
    42→
    43→  private final String function;
    44→
    45→  // This variable is lazily initialized to avoid unnecessary JavaScript compilation during JSON serde
    46→  private SelectorFunction fnSelector;
    47→
    48→  @JsonCreator
    49→  public JavaScriptTieredBrokerSelectorStrategy(
    50→      @JsonProperty("function") String fn,
    51→      @JacksonInject JavaScriptConfig config
    52→  )
    53→  {
    54→    Preconditions.checkNotNull(fn, "function must not be null");
    55→    Preconditions.checkState(config.isEnabled(), "JavaScript is disabled");
    56→
    57→    this.function = fn;
    58→  }
    59→
    60→  private SelectorFunction compileSelectorFunction()
    61→  {
    62→    final ScriptEngine engine = new ScriptEngineManager().getEngineByName("javascript");
    63→    try {
    64→      ((Compilable) engine).compile("var apply = " + function).eval();
    65→      return ((Invocable) engine).getInterface(SelectorFunction.class);
    66→    }
    67→    catch (ScriptException e) {
    68→      throw new RuntimeException(e);
    69→    }
    70→  }
    71→
    72→  @Override
    73→  public Optional<String> getBrokerServiceName(TieredBrokerConfig config, Query query)
    74→  {
    75→    fnSelector = fnSelector == null ? compileSelectorFunction() : fnSelector;
    76→    return Optional.fromNullable(fnSelector.apply(config, query));
    77→  }
    78→
    79→  @JsonProperty
    80→  public String getFunction()
    81→  {
    82→    return function;
    83→  }
    84→
    85→  @Override
    86→  public boolean equals(Object o)
    87→  {
    88→    if (this == o) {
    89→      return true;
    90→    }
    91→    if (o == null || getClass() != o.getClass()) {
    92→      return false;
    93→    }
    94→
    95→    JavaScriptTieredBrokerSelectorStrategy that = (JavaScriptTieredBrokerSelectorStrategy) o;
    96→
    97→    if (!function.equals(that.function)) {
    98→      return false;
    99→    }
   100→
   101→    return true;
   102→  }
   103→
   104→  @Override
   105→  public int hashCode()
   106→  {
   107→    return function.hashCode();
   108→  }
   109→
   110→  @Override
   111→  public String toString()
   112→  {
   113→    return "JavascriptTieredBrokerSelectorStrategy{" +
   114→           "function='" + function + '\'' +
   115→           '}';
   116→  }
   117→}
