    63→  {
    64→    final ScriptEngine engine = new ScriptEngineManager().getEngineByName("javascript");
    65→    try {
    66→      ((Compilable) engine).compile("var apply = " + function).eval();
    67→      return ((Invocable) engine).getInterface(SelectorFunction.class);
