    32→public class JavaScriptParser implements Parser<String, Object>
    33→{
    34→  private static Function<Object, Object> compile(String function)
    35→  {
    36→    final ContextFactory contextFactory = ContextFactory.getGlobal();
    37→    final Context context = contextFactory.enterContext();
    38→    context.setOptimizationLevel(9);
    39→
    40→    final ScriptableObject scope = context.initStandardObjects();
    41→
    42→    final org.mozilla.javascript.Function fn = context.compileFunction(scope, function, "fn", 1, null);
    43→    Context.exit();
    44→
    45→    return new Function<Object, Object>()
    46→    {
    47→      @Override
    48→      public Object apply(Object input)
    49→      {
    50→        // ideally we need a close() function to discard the context once it is not used anymore
    51→        Context cx = Context.getCurrentContext();
    52→        if (cx == null) {
    53→          cx = contextFactory.enterContext();
    54→        }
    55→
    56→        final Object res = fn.call(cx, scope, scope, new Object[]{input});
    57→        return res != null ? Context.toObject(res, scope) : null;
    58→      }
    59→    };
